// Store_API client for the backend `api` schema (PostgREST /rest/v1/rpc/<fn>).
// Browser and build-time. Uses only the public key (never the service key).
import { StoreApiError, toStoreError } from './errors';
import { clearCart, getCart } from '../storage';

export type Json = null | boolean | number | string | Json[] | { [k: string]: Json | undefined };
export type Args = Record<string, unknown>;

export interface StoreApiOptions {
  url?: string;
  key?: string;
  /** The signed-in session's access token; the public key is used otherwise. */
  getAccessToken?: () => string | null | undefined;
  fetch?: typeof fetch;
  timeoutMs?: number;
  /** Extra attempts for GETs after a network error, timeout or 502/503/504. */
  retries?: number;
  retryDelayMs?: number;
}

/** STABLE store reads, called with GET. Everything else is a POST. */
export const GET_FUNCTIONS: ReadonlySet<string> = new Set([
  'store_list_products', 'store_get_product', 'store_live_data', 'store_resolve_path', 'store_catalog_export',
  'store_delivery_rules', 'store_list_offers', 'store_check_postal_code', 'store_list_reviews', 'store_preview',
  'store_list_collections', 'store_list_categories', 'store_search_products', 'store_get_settings',
  // store_get_cart is VOLATILE in the database (PostgREST accepts only POST) and carries the Cart_Token: it is a POST.
]);

// Req 21.5: no amount other than the expected total leaves the browser.
const AMOUNT_KEY = /(^|_)(price|amount|total|discount|tax)(s)?($|_)/i;
const ALLOWED_AMOUNT_KEY = 'p_expected_total';

export function assertNoAmounts(value: unknown, path = 'args'): void {
  if (Array.isArray(value)) return value.forEach((v, i) => assertNoAmounts(v, `${path}[${i}]`));
  if (typeof value !== 'object' || value === null) return;
  for (const [k, v] of Object.entries(value)) {
    if (k !== ALLOWED_AMOUNT_KEY && AMOUNT_KEY.test(k)) throw new Error(`Store_API request must not carry "${k}" (${path})`);
    assertNoAmounts(v, `${path}.${k}`);
  }
}

function assertPublicKey(key: string): void {
  if (/^sb_secret_/.test(key)) throw new Error('The Store_API client must not use a service key');
  const part = key.split('.')[1];
  if (part) {
    try {
      const role = (JSON.parse(atob(part.replace(/-/g, '+').replace(/_/g, '/'))) as { role?: string }).role;
      if (role === 'service_role') throw new Error('The Store_API client must not use a service key');
    } catch (e) {
      if (e instanceof Error && e.message.includes('service key')) throw e;
    }
  }
}

const sleep = (ms: number) => new Promise((r) => setTimeout(r, ms));

export function createStoreApi(opts: StoreApiOptions = {}) {
  const env = (import.meta as unknown as { env?: Record<string, string | undefined> }).env ?? {};
  const base = (opts.url ?? env.PUBLIC_SUPABASE_URL ?? '').replace(/\/+$/, '');
  const key = opts.key ?? env.PUBLIC_SUPABASE_PUBLISHABLE_KEY ?? '';
  if (!base || !key) throw new Error('PUBLIC_SUPABASE_URL and PUBLIC_SUPABASE_PUBLISHABLE_KEY are required');
  assertPublicKey(key);
  const timeoutMs = opts.timeoutMs ?? 8000;
  const retries = opts.retries ?? 2;
  const retryDelayMs = opts.retryDelayMs ?? 250;

  async function once(fn: string, args: Args, get: boolean, idempotencyKey?: string): Promise<unknown> {
    const doFetch = opts.fetch ?? globalThis.fetch;
    const ctrl = new AbortController();
    const timer = setTimeout(() => ctrl.abort(), timeoutMs);
    const headers: Record<string, string> = {
      apikey: key,
      Authorization: `Bearer ${opts.getAccessToken?.() || key}`,
      Accept: 'application/json',
      'Accept-Profile': 'api',
    };
    let url = `${base}/rest/v1/rpc/${fn}`;
    const init: RequestInit = { method: get ? 'GET' : 'POST', headers, signal: ctrl.signal };
    if (get) {
      const q = new URLSearchParams();
      for (const [k, v] of Object.entries(args)) if (v !== undefined) q.set(k, typeof v === 'string' ? v : JSON.stringify(v));
      const s = q.toString();
      if (s) url += `?${s}`;
    } else {
      headers['Content-Type'] = 'application/json';
      headers['Content-Profile'] = 'api';
      if (idempotencyKey) headers['Idempotency-Key'] = idempotencyKey;
      init.body = JSON.stringify(args);
    }
    let res: Response;
    try {
      res = await doFetch(url, init);
    } catch (e) {
      throw new StoreApiError({ code: ctrl.signal.aborted ? 'timeout' : 'network_error', status: 0, message: e instanceof Error ? e.message : undefined });
    } finally {
      clearTimeout(timer);
    }
    let body: unknown = null;
    const text = await res.text().catch(() => '');
    if (text) {
      try {
        body = JSON.parse(text);
      } catch {
        body = null;
      }
    }
    // Expected rejections carry the envelope; some set status 200 with only {error}.
    const hasEnvelope = typeof body === 'object' && body !== null && !Array.isArray(body) && 'error' in body && (body as { error: unknown }).error;
    if (!res.ok || hasEnvelope) throw toStoreError(res.ok ? 400 : res.status, body, res.headers);
    return body;
  }

  async function call<T = unknown>(fn: string, args: Args = {}, o: { idempotencyKey?: string } = {}): Promise<T> {
    const get = GET_FUNCTIONS.has(fn);
    if (!get) assertNoAmounts(args);
    for (let attempt = 0; ; attempt++) {
      try {
        return (await once(fn, args, get, o.idempotencyKey)) as T;
      } catch (e) {
        const transient = e instanceof StoreApiError && (e.code === 'network_error' || e.code === 'timeout' || [502, 503, 504].includes(e.status));
        // Retry only reads. A write is never resent automatically (the shopper retries with the same Idempotency_Key).
        if (!get || !transient || attempt >= retries) throw e;
        await sleep(retryDelayMs * 2 ** attempt);
      }
    }
  }

  /** Cart calls: add p_cart_id and the Cart_Token from the device. */
  async function cartCall<T = unknown>(fn: string, args: Args = {}, o: { idempotencyKey?: string } = {}): Promise<T> {
    const cart = getCart();
    if (!cart) throw new StoreApiError({ code: 'not_found', status: 404, message: 'No cart on this device' });
    try {
      return await call<T>(fn, { ...args, p_cart_id: cart.id, p_cart_token: cart.token }, o);
    } catch (e) {
      if (e instanceof StoreApiError && e.code === 'not_found') clearCart();
      throw e;
    }
  }

  /** Creates one Idempotency_Key per confirmed placement; reuse it for every retry (Req 13.13). */
  const newIdempotencyKey = (): string => globalThis.crypto.randomUUID();

  /** Placement sends the shown total as the only amount (Req 13.10, 21.5). */
  function completeCart(idempotencyKey: string, expectedTotal: number) {
    return cartCall('store_complete_cart', { p_idempotency_key: idempotencyKey, p_expected_total: expectedTotal }, { idempotencyKey });
  }

  return { call, cartCall, newIdempotencyKey, completeCart };
}

export type StoreApi = ReturnType<typeof createStoreApi>;
