// Typed mapping of spec 1's error envelope: {"error": {code, message, fields?, details?}}.

export type StoreErrorCode =
  | 'totals_changed'
  | 'out_of_stock'
  | 'hold_time_exceeded'
  | 'cart_not_modifiable'
  | 'not_serviceable'
  | 'cod_not_eligible'
  | 'below_min_order_qty'
  | 'invalid_code'
  | 'promotion_rules_not_met'
  | 'promotion_invalid'
  | 'validation_failed'
  | 'bot_check_failed'
  | 'feature_disabled'
  | 'not_found'
  | 'rate_limited'
  | 'bot_check_unavailable'
  | 'provider_unavailable'
  | 'concurrency_conflict'
  | 'internal_error'
  | 'network_error'
  | 'timeout'
  | (string & {});

export class StoreApiError extends Error {
  readonly code: StoreErrorCode;
  readonly status: number;
  readonly fields?: Record<string, string>;
  readonly details?: unknown;
  readonly requestId?: string;
  /** Seconds from `Retry-After` (429, 503). */
  readonly retryAfter?: number;

  constructor(init: {
    code: StoreErrorCode;
    status: number;
    message?: string;
    fields?: Record<string, string>;
    details?: unknown;
    requestId?: string;
    retryAfter?: number;
  }) {
    super(init.message ?? init.code);
    this.name = 'StoreApiError';
    this.code = init.code;
    this.status = init.status;
    this.fields = init.fields;
    this.details = init.details;
    this.requestId = init.requestId;
    this.retryAfter = init.retryAfter;
  }

  /** When to try again, for `rate_limited` (Req 21.6). */
  get retryAt(): Date | undefined {
    return this.retryAfter == null ? undefined : new Date(Date.now() + this.retryAfter * 1000);
  }
  /** Safe to resend with the same Idempotency_Key. */
  get retryable(): boolean {
    return ['bot_check_unavailable', 'provider_unavailable', 'concurrency_conflict', 'internal_error', 'network_error', 'timeout'].includes(this.code);
  }
}

export const isRateLimited = (e: unknown): e is StoreApiError => e instanceof StoreApiError && e.code === 'rate_limited';

export function parseRetryAfter(value: string | null | undefined, now = Date.now()): number | undefined {
  if (!value) return undefined;
  const n = Number(value);
  if (Number.isFinite(n) && n >= 0) return Math.ceil(n);
  const t = Date.parse(value);
  return Number.isNaN(t) ? undefined : Math.max(0, Math.ceil((t - now) / 1000));
}

const isObj = (v: unknown): v is Record<string, unknown> => typeof v === 'object' && v !== null && !Array.isArray(v);

export function toStoreError(status: number, body: unknown, headers: Headers): StoreApiError {
  const env = isObj(body) ? (isObj(body.error) ? body.error : body) : {};
  const fields = isObj(env.fields) ? (env.fields as Record<string, string>) : undefined;
  const requestId =
    headers.get('x-request-id') ?? (typeof env.request_id === 'string' ? env.request_id : undefined) ??
    (isObj(body) && typeof body.request_id === 'string' ? body.request_id : undefined);
  const code = typeof env.code === 'string' ? env.code : status === 429 ? 'rate_limited' : status === 404 ? 'not_found' : 'internal_error';
  return new StoreApiError({
    code,
    status,
    message: typeof env.message === 'string' ? env.message : undefined,
    fields,
    details: env.details,
    requestId,
    retryAfter: parseRetryAfter(headers.get('retry-after')),
  });
}
